function parseList(html, context) {
  var ctx = context || {};
  var baseUrl = (ctx.baseUrl || 'https://www.baozimh.com').replace(/\/$/, '');
  var listHtml = (typeof html === 'string') ? html : '';
  try { if (ctx.log) ctx.log('parseList: htmlLen=' + listHtml.length); } catch(e){}
  var results = [];
  if (!listHtml || listHtml.length < 50) return results;
  var seen = {};
  var aRe = /<a\s+([^>]*)>([\s\S]*?)<\/a>/gi;
  var m;
  while ((m = aRe.exec(listHtml)) !== null) {
    var attrs = m[1];
    var block = m[2];
    var hm = attrs.match(/href="([^"]+)"/i);
    if (!hm) continue;
    var href = hm[1];
    if (href.indexOf('/manga/') !== 0) continue;
    if (seen[href]) continue;
    var imgM = block.match(/<img[^>]*\bsrc="([^"]+)"[^>]*>/i) || block.match(/<img[^>]*\bdata-src="([^"]+)"[^>]*>/i);
    var titleM = block.match(/<h3[^>]*>([\s\S]*?)<\/h3>/i);
    if (!imgM || !titleM) continue;
    var stripTags = function(s){ return s.replace(/<[^>]+>/g, '').replace(/\s+/g, ' ').trim(); };
    var title = stripTags(titleM[1]);
    if (!title) continue;
    var cover = imgM[1];
    if (cover.indexOf('/') === 0) cover = baseUrl + cover;
    seen[href] = 1;
    var slug = href.replace(/^\/manga\//, '');
    results.push({ id: slug, title: title, cover: cover, detailUrl: baseUrl + href });
  }
  try { if (ctx.log) ctx.log('parseList: found=' + results.length); } catch(e){}
  return results;
}

