  if (!mid) {
    var mangaIdMatch = html.match(/id=["']mangachapters["'][^>]*data-mid=["'](\d+)["']/i);
    if (mangaIdMatch) mid = mangaIdMatch[1];
  }
  if (!mid) return [];
  var apiUrl = 'https://v2.apikk.top/api/manga/get?mid=' + mid + '&mode=all&t=' + Date.now();
